"use strict";

/**
 * A release body's Security section: the advisories that the Dependabot PRs
 * merged in that release clear (#1693).
 *
 * Source of truth: the operations repo's `scripts/fleet-checks/`; the shared
 * workflow repo's copy is generated by `publish.sh` and never hand-edited.
 *
 * A security fix made by hand carries a `type: fixed` fragment, but the
 * fragment check exempts bot-authored PRs, and Dependabot opens most security
 * fixes. So the generator writes these lines itself, from two readings:
 *
 *   1. git: the Dependabot commits between the stream's previous tag and this
 *      one that touch the stream's paths, and the bumps their messages name
 *      ("bump X from A to B", "Updates `X` from A to B"). A squash whose
 *      message the merger rewrote names no bump, so its PR body is read instead.
 *   2. GitHub: the repository's FIXED Dependabot alerts.
 *
 * A bump is a security fix when it moves a package from below an alert's first
 * patched version to at or past it. That is the rule because the two kinds of
 * Dependabot PR look alike everywhere else: same author, same branch prefix,
 * and a security update's body names no advisory (measured 2026-11-03).
 *
 * ⚠️ AN UNREADABLE READ IS SAID, NEVER RENDERED AS AN EMPTY SECTION.
 * Examined-nothing is not found-nothing: alerts that could not be read, or a
 * commit whose bumps could not be read, are named in the section. A release
 * with no Dependabot commits in range needs no read and gets no section.
 */

const { execFileSync } = require("node:child_process");
const { compareVersions, inStream, isPrerelease, prNumber } = require("./changelog.js");

const run = (root, args) => execFileSync("git", args, { cwd: root, encoding: "utf8", maxBuffer: 256 * 1024 * 1024 });

/** A squash merge keeps the PR's author; a merge commit names the branch it merged. */
const isDependabotCommit = ({ author, subject }) =>
  /^dependabot(\[bot\])?$/i.test(author) || /^Merge pull request #\d+ from \S+\/dependabot\//.test(subject);

const VERSION = "v?(\\d[\\w.+-]*?)";
const END = "(?=[.,;:)]?(?:\\s|$))";
const BUMP_PATTERNS = [
  // the title or lead line: "bump vite from 7.3.6 to 7.3.7", "Bumps [vite](…) from 7.3.6 to 7.3.7."
  new RegExp(`\\bbumps? \\[?([@\\w][\\w@./-]*)\\]?(?:\\([^)]*\\))? from ${VERSION} to ${VERSION}${END}`, "gi"),
  // one line per package, which a grouped or multi-package update has: "Updates `x` from 1.0 to 1.1"
  new RegExp(`\\bUpdates \`([^\`]+)\` from ${VERSION} to ${VERSION}${END}`, "g"),
];

/** Each bump a Dependabot message names, once per package. */
function parseBumps(message) {
  const by = new Map();
  for (const re of BUMP_PATTERNS) {
    for (const m of message.matchAll(re)) if (!by.has(m[1])) by.set(m[1], { name: m[1], from: m[2], to: m[3] });
  }
  return [...by.values()];
}

/**
 * The tag a release's range starts after, by the rule `releaseEntries` uses:
 * a pre-release's previous reached tag of any kind, a stable release's previous
 * reached stable tag. `null` means the range is the whole history.
 */
function previousTag(tag, { streamTags, prefix, reaches }) {
  const v = (t) => t.slice(prefix.length);
  const before = streamTags.filter((t) => t !== tag && reaches.has(t) && compareVersions(v(t), v(tag)) < 0);
  const pool = isPrerelease(tag, prefix) ? before : before.filter((t) => !isPrerelease(t, prefix));
  return pool.pop() ?? null;
}

/**
 * The Dependabot commits on `ref`'s first-parent line after `since` that touch
 * the stream. First-parent, so a merged Dependabot branch counts once, as its merge.
 */
function dependabotCommits(root, { ref, since, stream }) {
  const range = since ? [`refs/tags/${since}..${ref}`] : [ref];
  const out = run(root, ["log", "--first-parent", "--format=%H%x1f%an%x1f%s%x1f%b%x1e", ...range]);
  const commits = [];
  for (const rec of out.split("\x1e")) {
    const [sha, author, subject, body = ""] = rec.replace(/^\n/, "").split("\x1f");
    if (!sha || !isDependabotCommit({ author, subject })) continue;
    const parent = run(root, ["rev-list", "--parents", "-n", "1", sha]).trim().split(" ")[1];
    const paths = parent ? run(root, ["diff", "--name-only", "--no-renames", parent, sha]).split("\n").filter(Boolean) : [];
    if (!paths.some((p) => inStream(p, stream))) continue;
    commits.push({ sha, pr: prNumber(subject), bumps: parseBumps(`${subject}\n${body}`) });
  }
  return commits;
}

/** A PR's body, through `gh`. Throws when unreadable. */
function readPrBody(root, number) {
  return execFileSync("gh", ["api", `repos/{owner}/{repo}/pulls/${number}`, "--jq", '.body // ""'],
    { cwd: root, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] });
}

/**
 * The repository's fixed Dependabot alerts, through `gh` (authenticated where
 * release scripts run, and by GH_TOKEN / GITHUB_TOKEN in a workflow). `gh`
 * fills `{owner}/{repo}` from the checkout's remote. Throws when unreadable:
 * no `gh`, no permission, or alerts turned off.
 */
function readFixedAlerts(root) {
  const jq = ".[] | {name: .dependency.package.name, ghsa: .security_advisory.ghsa_id, cve: .security_advisory.cve_id, patched: .security_vulnerability.first_patched_version.identifier}";
  const out = execFileSync("gh", ["api", "--paginate", "repos/{owner}/{repo}/dependabot/alerts?state=fixed&per_page=100", "--jq", jq],
    { cwd: root, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"], maxBuffer: 64 * 1024 * 1024 });
  return out.split("\n").filter(Boolean).map((l) => JSON.parse(l));
}

const firstLine = (e) => String(e?.stderr || e?.message || e).trim().split("\n")[0].slice(0, 200);

/**
 * The security fixes a release ships.
 *
 * @returns {{status: "none"|"ok"|"unreadable", commits: number, items: object[], unchecked: object[], reason?: string}}
 *   `none`: no Dependabot commit in range, so nothing was read. `ok`: the items
 *   (possibly none) the alerts confirm, plus `unchecked`, the commits whose bumps
 *   could be read from neither their message nor their PR. `unreadable`: the
 *   alerts could not be read.
 */
function securityFixes({ root, ref, since, stream, readAlerts = readFixedAlerts, readBody = readPrBody }) {
  const commits = dependabotCommits(root, { ref, since, stream });
  if (!commits.length) return { status: "none", commits: 0, items: [], unchecked: [] };
  const unchecked = [];
  for (const c of commits) {
    if (c.bumps.length) continue;
    if (c.pr === null) { unchecked.push({ sha: c.sha, pr: null, reason: "its message names no bump and no PR" }); continue; }
    try { c.bumps = parseBumps(String(readBody(root, c.pr))); } catch (e) { unchecked.push({ sha: c.sha, pr: c.pr, reason: firstLine(e) }); continue; }
    if (!c.bumps.length) unchecked.push({ sha: c.sha, pr: c.pr, reason: "neither its message nor its PR names a bump" });
  }
  let alerts;
  try { alerts = readAlerts(root); } catch (e) { return { status: "unreadable", commits: commits.length, items: [], unchecked, reason: firstLine(e) }; }
  if (!Array.isArray(alerts)) return { status: "unreadable", commits: commits.length, items: [], unchecked, reason: "the alert read returned no list" };
  const items = [];
  for (const c of commits) {
    for (const b of c.bumps) {
      const cleared = alerts.filter((a) => a.name === b.name && a.patched && a.ghsa &&
        compareVersions(b.from, a.patched) < 0 && compareVersions(b.to, a.patched) >= 0);
      const seen = new Set();
      const advisories = cleared.filter((a) => !seen.has(a.ghsa) && seen.add(a.ghsa)).map(({ ghsa, cve }) => ({ ghsa, cve: cve || null }));
      if (advisories.length) items.push({ ...b, pr: c.pr, sha: c.sha, advisories });
    }
  }
  return { status: "ok", commits: commits.length, items, unchecked };
}

const advisoryLink = ({ ghsa, cve }) => `[${ghsa}](https://github.com/advisories/${ghsa})${cve ? ` (${cve})` : ""}`;

/** The section's markdown, or "" when there is nothing to say. */
function renderSecurity(r) {
  if (r.status === "unreadable") {
    return `### Security\n\n_The Security section could not be read: ${r.reason}. ` +
      `${r.commits} Dependabot commit(s) in this release were not checked against the repository's advisories._\n`;
  }
  if (r.status !== "ok" || (!r.items.length && !r.unchecked.length)) return "";
  const lines = [...r.items]
    .sort((a, b) => a.name.localeCompare(b.name) || (b.pr ?? 0) - (a.pr ?? 0))
    .map((i) => `- \`${i.name}\` ${i.from} → ${i.to}: ${i.advisories.map(advisoryLink).join(", ")}${i.pr ? ` (PR #${i.pr})` : ""}`);
  // A commit whose bumps could not be read is named, never dropped: it may be the one that cleared an advisory.
  if (r.unchecked.length) {
    const which = r.unchecked.map((u) => (u.pr ? `PR #${u.pr}` : u.sha.slice(0, 7))).join(", ");
    lines.push(`- _Not checked: ${r.unchecked.length} Dependabot commit(s) whose bumps could not be read (${which})._`);
  }
  return `### Security\n\n${lines.join("\n")}\n`;
}

module.exports = { isDependabotCommit, parseBumps, previousTag, dependabotCommits, readPrBody, readFixedAlerts, securityFixes, renderSecurity };
